import javax.servlet.http.HttpServlet;
import javax.servlet.http.HttpServletRequest;
import javax.servlet.http.HttpServletResponse;
import java.io.IOException;
import java.util.logging.Logger;

/** 请求追踪日志（变体3）：记录搜索请求的追踪信息 */
public class RequestTraceServlet extends HttpServlet {

    private static final Logger TRACE_LOG = Logger.getLogger("request.trace");

    @Override
    protected void doGet(HttpServletRequest req, HttpServletResponse resp) throws IOException {
        String username = req.getParameter("username");
        String keyword = req.getParameter("q");
        String userAgent = req.getHeader("User-Agent");

        String traceId = "T-" + System.currentTimeMillis();

        String traceLine = String.format(
                "TRACE id=%s user=%s action=search keyword=%s ua=%s",
                traceId, username, keyword, userAgent);

        TRACE_LOG.info(traceLine);

        resp.setStatus(HttpServletResponse.SC_OK);
    }
}
