        String tradeStatus = extractField(body, "trade_status");
        auditLog.info("PAY_CALLBACK ip=" + clientIp + " out_trade_no=" + outTradeNo
                + " trade_status=" + tradeStatus);
        if ("TRADE_SUCCESS".equals(tradeStatus)) {
            auditLog.info("PAY_CALLBACK ORDER_PAID out_trade_no=" + outTradeNo);
            markPaid(outTradeNo);
        }
    }

