import java.util.logging.Logger;
import javax.servlet.http.HttpServletRequest;
import javax.servlet.http.HttpServletResponse;
import java.io.IOException;

public class LoginAuditService {

    private static final Logger logger = Logger.getLogger(LoginAuditService.class.getName());

    // 登录接口：校验凭据并写入登录审计日志
    public void handleLogin(HttpServletRequest request, HttpServletResponse response) throws IOException {
        String username = request.getParameter("username");
        String password = request.getParameter("password");
        String clientIp = request.getHeader("X-Forwarded-For");

        if (username == null || password == null) {
            response.sendError(400);
            return;
        }

        boolean success = authenticate(username, password);
        String status = success ? "SUCCESS" : "FAILURE";

        // 审计日志写入点：username 与 clientIp 作为数据实参填入 %s 占位符
        logger.info(String.format("AUDIT LOGIN result=%s user=%s ip=%s", status, username, clientIp));

        response.getWriter().write(success ? "ok" : "denied");
    }

    private boolean authenticate(String user, String pwd) {
        return user.length() >= 3 && pwd.length() >= 8;
    }
}
