import java.sql.Connection;
import java.sql.DriverManager;
import java.sql.PreparedStatement;
import java.sql.SQLException;
import java.util.logging.Logger;
import javax.servlet.http.HttpServletRequest;

public class AlertRecordDao {

    private static final Logger LOGGER = Logger.getLogger(AlertRecordDao.class.getName());

    // 告警源系统上报安全告警事件，需携带其访问令牌供平台后续回查校验
    public void saveAlert(HttpServletRequest request) throws SQLException {
        String alertId = request.getParameter("alertId");
        String level = request.getParameter("level");
        String sourceToken = request.getParameter("sourceToken"); // 外部输入：告警源访问令牌

        LOGGER.info("received security alert event, persisting to alertdb");

        try (Connection conn = DriverManager.getConnection(System.getenv("ALERT_DB_URL"));
                PreparedStatement ps = conn.prepareStatement(
                        "INSERT INTO security_alert(alert_id, level, source_token) VALUES (?, ?, ?)")) {
            ps.setString(1, alertId);
            ps.setString(2, level);
            ps.setString(3, sourceToken); // 令牌未加密未脱敏直接入库
            ps.executeUpdate();
        }
    }
}
