import com.sun.net.httpserver.HttpServer;
import com.sun.net.httpserver.HttpExchange;
import org.slf4j.Logger;
import org.slf4j.LoggerFactory;
import java.io.OutputStream;
import java.net.InetSocketAddress;
import java.nio.charset.StandardCharsets;

public class DeployLogService {
    private static final Logger DEPLOY_LOG = LoggerFactory.getLogger(DeployLogService.class);

    public static void main(String[] args) throws Exception {
        HttpServer server = HttpServer.create(new InetSocketAddress(8083), 0);
        server.createContext("/ops/deploy/log", DeployLogService::handleDeployLog);
        server.start();
    }

    // 运维部署平台回调：发布人员在控制台填写 stage 描述，平台原样转发
    static void handleDeployLog(HttpExchange exchange) throws java.io.IOException {
        String query = exchange.getRequestURI().getQuery();   // stage=<发布描述>&build=<构建号>
        String stage = "";
        String build = "unknown";
        if (query != null) {
            for (String kv : query.split("&")) {
                if (kv.startsWith("stage=")) stage = kv.substring(6);
                if (kv.startsWith("build=")) build = kv.substring(6);
            }
        }
        // 运维约定：stage 直接充当日志模板，build 作为 {} 的填充参数
        DEPLOY_LOG.info(stage, build);
        byte[] body = "deploy log recorded".getBytes(StandardCharsets.UTF_8);
        exchange.sendResponseHeaders(200, body.length);
        try (OutputStream os = exchange.getResponseBody()) { os.write(body); }
    }
}
