// trace-logger.js —— 请求追踪日志服务（变体1）：客户端可自定义追踪模板
const http = require('http');
const util = require('util');

// 追踪日志器：第一个参数作为格式串交给 util.format 解析
function writeTrace(format, ...args) {
  const line = util.format(format, ...args); // 格式串解析点
  process.stdout.write('[TRACE] ' + line + '\n');
}

const server = http.createServer((req, res) => {
  const url = new URL(req.url, 'http://trace.internal');
  // 外部输入入口：查询参数 trace 指定追踪日志模板
  const traceTemplate = url.searchParams.get('trace');

  if (traceTemplate) {
    // 漏洞点：traceTemplate 占据格式串参数位（第 1 参），x-request-id 只是数据位
    writeTrace(traceTemplate, req.headers['x-request-id']);
  } else {
    writeTrace('request %s handled', req.headers['x-request-id']); // 正确写法：固定模板
  }

  res.end('ok');
});

server.listen(8080, () => console.log('trace service on 8080'));
