  // 渠道对接文档约定：channelMsg 可含 %s/%d 占位符，渲染时依次引用 orderNo、amount
  payLog(channelMsg, orderNo, amount);

  if (status === 'SUCCESS') {
    payLog('order %s settled, amount=%d', orderNo, amount);
  }
  res.send('success');
});

